import {setTimeout as delay} from 'node:timers/promises';
import test from 'ava';
import pLimit, {limitFunction} from './index.js';

test('onIdle resolves immediately when already idle', async t => {
	const limit = pLimit(1);

	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);

	await t.notThrowsAsync(limit.onIdle());
});

test('onIdle waits for running tasks to settle', async t => {
	const limit = pLimit(2);
	let completed = 0;

	const promises = Array.from({length: 4}, () => limit(async () => {
		await delay(20);
		completed++;
	}));

	await limit.onIdle();

	t.is(completed, 4);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
	await Promise.all(promises);
});

test('onIdle works with multiple waiters', async t => {
	const limit = pLimit(1);
	const order = [];

	const task = limit(async () => {
		await delay(30);
	});

	const waiters = Array.from({length: 5}, () => limit.onIdle().then(() => {
		order.push('idle');
	}));

	await Promise.all(waiters);
	await task;

	t.is(order.length, 5);
	t.is(limit.activeCount, 0);
});

test('onIdle resets so it can be awaited again', async t => {
	const limit = pLimit(1);

	await limit.onIdle();

	limit(() => delay(10));
	await limit.onIdle();

	await limit(async () => delay(10));
	await t.notThrowsAsync(limit.onIdle());
});

test('onIdle waits for rejected jobs', async t => {
	const limit = pLimit(1);
	const error = new Error('🦄');

	const promises = [
		limit(async () => {
			await delay(10);
			throw error;
		}),
		limit(async () => delay(10)),
	];
	promises[0].catch(() => {});
	const all = Promise.all(promises).catch(() => {});

	await limit.onIdle();

	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
	await all;
});

test('onIdle does not report idle early when a settling job enqueues another job', async t => {
	const limit = pLimit(1);
	const completed = [];

	const first = limit(async () => {
		limit(async () => {
			await delay(30);
			completed.push('second');
		});
		completed.push('first');
	});

	await limit.onIdle();

	t.deepEqual(completed, ['first', 'second']);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
	await first;
});

test('onIdle waits for a job enqueued from a then handler', async t => {
	const limit = pLimit(1);
	const completed = [];

	const first = limit(async () => {
		completed.push('first');
	}).then(() => limit(async () => {
		await delay(20);
		completed.push('second');
	}));

	await limit.onIdle();

	t.deepEqual(completed, ['first', 'second']);
	t.is(limit.activeCount, 0);
	await first;
});

test('onIdle counts reserved slots as active', async t => {
	const limit = pLimit(1);

	// This task is reserved (activeCount incremented) but has not started running yet.
	limit(() => delay(50));
	t.is(limit.activeCount, 1);

	let idle = false;
	const idlePromise = limit.onIdle().then(() => {
		idle = true;
	});

	await Promise.resolve();
	t.false(idle);

	await idlePromise;
	t.true(idle);
});

test('clearQueue releases onIdle waiters when no jobs are active (rejectOnClear: false)', async t => {
	const limit = pLimit({concurrency: 1, rejectOnClear: false});

	// Only pending jobs. They stay unresolved after clearQueue.
	const pending = limit(() => delay(1000));
	await Promise.resolve();
	t.is(limit.pendingCount, 1);
	t.is(limit.activeCount, 0);

	let idle = false;
	const idlePromise = limit.onIdle().then(() => {
		idle = true;
	});

	limit.clearQueue();
	await idlePromise;

	t.true(idle);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);

	// The discarded promise intentionally stays unresolved.
	await Promise.race([pending.then(() => 'settled'), delay(10).then(() => 'pending')]).then(result => {
		t.is(result, 'pending');
	});
});

test('clearQueue releases onIdle waiters when no jobs are active (rejectOnClear: true)', async t => {
	const limit = pLimit({concurrency: 1, rejectOnClear: true});

	const pending = limit(() => delay(1000));
	pending.catch(() => {});
	await Promise.resolve();

	const idlePromise = limit.onIdle();
	limit.clearQueue();

	await idlePromise;
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
});

test('clearQueue does not release onIdle while jobs are active', async t => {
	const limit = pLimit({concurrency: 1, rejectOnClear: false});

	limit(() => delay(30));
	limit(() => delay(1000));
	await Promise.resolve();

	let idle = false;
	const idlePromise = limit.onIdle().then(() => {
		idle = true;
	});

	limit.clearQueue();
	await Promise.resolve();
	t.false(idle);

	await idlePromise;
	t.true(idle);
});

test('onIdle respects concurrency changes', async t => {
	const limit = pLimit(1);
	const completed = [];

	Array.from({length: 4}, () => limit(async () => {
		await delay(15);
		completed.push(1);
	}));

	await Promise.resolve();
	limit.concurrency = 2;

	await limit.onIdle();

	t.is(completed.length, 4);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
});

test('limitFunction exposes onIdle', async t => {
	const limitedFunction = limitFunction(() => delay(20), {concurrency: 1});

	await limitedFunction.onIdle();

	const running = limitedFunction();
	const pending = limitedFunction();

	let idle = false;
	const idlePromise = limitedFunction.onIdle().then(() => {
		idle = true;
	});

	await Promise.resolve();
	t.false(idle);

	await idlePromise;
	t.true(idle);
	await Promise.all([running, pending]);
});

