test('clearQueue directly releases onIdle waiters when the queue is cleared and nothing is active', async t => {
	const limit = pLimit({concurrency: 2, rejectOnClear: false});

	// Reserve both slots synchronously, then queue a third job while the reserved
	// slots are still counted as active.
	const running = [limit(() => delay(20)), limit(() => delay(20))];
	const pending = limit(() => delay(1000));

	t.is(limit.activeCount, 2);
	t.is(limit.pendingCount, 1);

	// Drop the concurrency so the queued job can never be promoted. The two
	// reserved slots finish, leaving no active jobs and only a cleared queue.
	limit.concurrency = 1;

	let idle = false;
	const idlePromise = limit.onIdle().then(() => {
		idle = true;
	});

	limit.clearQueue();

	await idlePromise;
	t.true(idle);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
	await Promise.all(running);

	const result = await Promise.race([pending.then(() => 'settled'), delay(10).then(() => 'pending')]);
	t.is(result, 'pending');
});

