import {setTimeout as delay} from 'node:timers/promises';
import test from 'ava';
import pLimit, {limitFunction} from './index.js';

test('onIdle resolves immediately when already idle', async t => {
	const limit = pLimit(1);

	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);

	await t.notThrowsAsync(limit.onIdle());
});

test('onIdle waits for running tasks to settle', async t => {
	const limit = pLimit(2);
	let completed = 0;

	const promises = Array.from({length: 4}, () => limit(async () => {
		await delay(20);
		completed++;
	}));

	await limit.onIdle();

	t.is(completed, 4);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
	await Promise.all(promises);
});

test('onIdle works with multiple waiters', async t => {
	const limit = pLimit(1);
	const order = [];

	const task = limit(async () => {
		await delay(30);
	});

	const waiters = Array.from({length: 5}, async () => {
		await limit.onIdle();
		order.push('idle');
	});

	await Promise.all(waiters);
	await task;

	t.is(order.length, 5);
	t.is(limit.activeCount, 0);
});

test('onIdle resets so it can be awaited again', async t => {
	const limit = pLimit(1);

	await limit.onIdle();

	limit(() => delay(10));
	await limit.onIdle();

	await limit(async () => delay(10));
	await t.notThrowsAsync(limit.onIdle());
});

test('onIdle waits for rejected jobs', async t => {
	const limit = pLimit(1);
	const error = new Error('🦄');

	const promises = [
		limit(async () => {
			await delay(10);
			throw error;
		}),
		limit(async () => delay(10)),
	];

	const all = (async () => {
		try {
			await Promise.all(promises);
		} catch {}
	})();

	await limit.onIdle();

	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
	await all;
});

test('onIdle does not report idle early when a settling job enqueues another job', async t => {
	const limit = pLimit(1);
